import collections,json,pathlib
p=pathlib.Path("research/results/rank_three_bottom_source_20260914_140/rank-three-source-checks.jsonl")
counts=collections.Counter();selected=[]
with p.open() as f:
    for line in f:
        r=json.loads(line);counts[r["record"]]+=1
        if r["record"] in ("summary","rank_three_combined_summary","branch_closure_summary"):
            selected.append(r)
        elif r["record"]=="triple_quotient_count":
            selected.append({k:r[k] for k in ("record","v","triples","k","homogeneous_domain","quotient_through_degree","full_monomial_enumeration")})
        elif r["record"]=="triple_finite_parameters":
            selected.append({k:r[k] for k in ("record","ell","source_D","normalized_D0","range_space_image_conditions","old_degree_condition")})
print(json.dumps({"record_counts":dict(counts),"selected":selected},indent=2))
